query:
query WorkspacePageWithCounts($organizationIds: [String], $first: StringOrInt, $after: StringOrInt, $filter: String!, $sort: String, $statusAll: String!, $status_waitingApproval: String!, $status_failed: String!, $status_pending: String!, $status_queue: String!, $status_running: String!, $status_completed: String!, $status_NeverExecuted: String!, $policyAll: String!, $policy_COMPLIANT: String!, $policy_NON_COMPLIANT: String!, $policy_EXEMPTED: String!, $policy_UNKNOWN: String!) {
  organization(ids: $organizationIds) {
    edges {
      node {
        name
        workspace(first: $first, after: $after, filter: $filter, sort: $sort) {
          edges {
            node {
              ...WorkspaceListFields
            }
          }
          pageInfo {
            endCursor
            hasNextPage
            totalRecords
          }
        }
        statusAll: workspace(first: "1", filter: $statusAll) {
          pageInfo {
            totalRecords
          }
        }
        status_waitingApproval: workspace(first: "1", filter: $status_waitingApproval) {
          pageInfo {
            totalRecords
          }
        }
        status_failed: workspace(first: "1", filter: $status_failed) {
          pageInfo {
            totalRecords
          }
        }
        status_pending: workspace(first: "1", filter: $status_pending) {
          pageInfo {
            totalRecords
          }
        }
        status_queue: workspace(first: "1", filter: $status_queue) {
          pageInfo {
            totalRecords
          }
        }
        status_running: workspace(first: "1", filter: $status_running) {
          pageInfo {
            totalRecords
          }
        }
        status_completed: workspace(first: "1", filter: $status_completed) {
          pageInfo {
            totalRecords
          }
        }
        status_NeverExecuted: workspace(first: "1", filter: $status_NeverExecuted) {
          pageInfo {
            totalRecords
          }
        }
        policyAll: workspace(first: "1", filter: $policyAll) {
          pageInfo {
            totalRecords
          }
        }
        policy_COMPLIANT: workspace(first: "1", filter: $policy_COMPLIANT) {
          pageInfo {
            totalRecords
          }
        }
        policy_NON_COMPLIANT: workspace(first: "1", filter: $policy_NON_COMPLIANT) {
          pageInfo {
            totalRecords
          }
        }
        policy_EXEMPTED: workspace(first: "1", filter: $policy_EXEMPTED) {
          pageInfo {
            totalRecords
          }
        }
        policy_UNKNOWN: workspace(first: "1", filter: $policy_UNKNOWN) {
          pageInfo {
            totalRecords
          }
        }
      }
    }
  }
}

fragment WorkspaceListFields on Workspace {
  id
  name
  description
  source
  branch
  terraformVersion
  iacType
  lastJobStatus
  lastJobDate
  locked
  policyComplianceStatus
  workspaceTag {
    edges {
      node {
        tagId
        value
      }
    }
  }
  project {
    edges {
      node {
        id
        name
      }
    }
  }
}
